```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitLoss;

  Transaction(this.coinName, this.datetime, this.profitLoss);
}

Map<String, double> calculateAverageProfitLoss(List<Transaction> transactions) {
  Map<String, double> coinData = {};

  for (Transaction transaction in transactions) {
    if (coinData.containsKey(transaction.coinName)) {
      coinData[transaction.coinName] += transaction.profitLoss;
    } else {
      coinData[transaction.coinName] = transaction.profitLoss;
    }
  }

  return coinData;
}

List<dynamic> getTopCoins({required List<Transaction> transactions, required bool isProfit}) {
  Map<String, double> averages = calculateAverageProfitLoss(transactions);
  List<dynamic> topCoins = [];

  var sortedCoins = SortedMap<double, String>.fromEntries(averages.entries);
  int index = 1;
  while (topCoins.length < 3 && index <= 3) {
    if (isProfit) {
      topCoins.add(sortedCoins.values.elementAt(index++));
    } else {
      topCoins.add(sortedCoins.keys.elementAt(index - 1));
    }
  }

  return topCoins;
}

