```javascript
function recommendCarSize(customerHeight) {
  // Parse the JSON data
  const carSizes = JSON.parse(jsonData).carSizes;

  // Filter the car sizes based on the customer's height
  const eligibleCarSizes = Object.values(carSizes).filter((carSize) => {
    return customerHeight >= carSize.heightRange.split(" - ")[0] && customerHeight <= carSize.heightRange.split(" - ")[1];
  });

  // Sort the eligible car sizes in ascending order of length
  const sortedCarSizes = eligibleCarSizes.sort((a, b) => a.length < b.length);

  // Return the first (smallest) eligible car size
  return sortedCarSizes[0].name;
}
