```csharp using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _baseAddress;
    private string _authToken;

    public RestServiceWrapper(string baseAddress)
    {
        _baseAddress = baseAddress;
        _httpClient = new HttpClient();
    }

    public void SetAuthToken(string authToken)
    {
        _authToken = authToken;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
    }

    public async Task<HttpResponseMessage> GetAsync(string requestUrl)
    {
        return await _httpClient.GetAsync($"{_baseAddress}/{requestUrl}");
    }

    public async Task<HttpResponseMessage> PostAsync(string requestUrl, HttpContent content)
    {
        return await _httpClient.PostAsync($"{_baseAddress}/{requestUrl}", content);
    }

    // Add similar methods for Put and Delete if needed
}

// Usage:
