5. Check for successful login:

```javascript
LoginManager.onLoginFinished((result) => {
  if (result.isCancelled) {
    console.log("Login cancelled");
  } else {
    AccessToken.getCurrentAccessToken().then((data) => {
      // data is the access token received after a successful login
      console.log("Successfully logged in with permissions:", data.grantedPermissions);
    });
  }
});
```

6. If you want to handle the response asynchronously, you can also check the login status:

```javascript
LoginManager.getLogInStatus().then((loginState) => {
  if (loginState.isLoggedIn) {
    AccessToken.getCurrentAccessToken().then((data) => {
      // data is the access token received when a user is already logged in
      console.log("User is already logged in, data:", data);
    });
  } else {
    console.log("User is not logged in");
  }
});
```

