The Datamuse API (https://www.datamuse.com/) has a feature to search for antonyms. Here's how you can use it:

1. First, install the `axios` library if you haven't already: https://www.npmjs.com/package/axios

2. Create a new JavaScript file and add the following code snippet:

```javascript
const axios = require('axios');

async function getAntonyms(word) {
  try {
    const response = await axios.get(`https://api.datamuse.com/words?rel_antonym=${word}`);
    return response.data;
  } catch (error) {
    console.log("Error: ", error);
  }
}

function printAntonyms(antonyms) {
  if (Array.isArray(antonyms)) {
    console.log("Antonyms for 'aesthetic':");
    antonyms.forEach((antonym, index) => {
      console.log(`${index + 1}. ${antonym.word}`);
    });
  } else {
    console.log("No antonyms found.");
  }
}

getAntonyms('aesthetic')
  .then(printAntonyms)
  .catch(err => console.error(err));
```

3. Save this code in a file named `findAntonyms.js`.

4. Run the script using Node.js: `node findAntonyms.js`

This script will print out the antonyms for the word "aesthetic" in the console. The output will look something like this:

```
Antonyms for 'aesthetic':
1. unaesthetic
2. unattractive
3. ugly
...
```

