import React, { useState } from 'react';
import { useCombobox } from 'downshift';
import AutoSuggest from 'react-autosuggest';

async function searchEmails(prefix: string): Promise<string[]> {
  // Implement your email searching logic here
  const response = await fetch('/api/searchEmails?prefix=' + prefix);
  return response.json();
}

interface Option {
  value: string;
  label: string;
}

interface ComboboxProps {
  onChange: (email: string) => void;
}

const EmailInput: React.FC<ComboboxProps> = ({ onChange }) => {
  const [items, setItems] = useState<Option[]>([]);
  const { isOpen, getMenuProps, getInputProps, highlightedIndex, getItemProps } = useCombobox({
    items,
    onInputValueChange: async ({ newInputValue }) => {
      const results = await searchEmails(newInputValue);
      setItems(results.map((email) => ({ value: email, label: email })));
    },
  });

  const handleSelect = (item: Option) => {
    onChange(item.value);
    setItems([]);
  };

  return (
    <div>
      <input {...getInputProps()} placeholder="Enter email" />
      <ul {...getMenuProps()}>
        {isOpen &&
          items.map((item, index) => (
            <li key={item.value} {...getItemProps({ item, index })} onClick={() => handleSelect(item)}>
              <span>{item.label}</span>
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInput;
```

