using namespace std;
void printPermutations(const string& str, int l, int r, vector<string>& arr) {
    if (l == r) {
        arr.push_back(str);
        return;
    }
    for (int i = l; i <= r; ++i) {
        swap(str[l], str[i]);
        printPermutations(str, l+1, r, arr);
        swap(str[l], str[i]); // backtrack
