 Here's the code you can use to create the `RedisClient` class with the required functions in the `redis.js` file:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error(`Error connecting to Redis: ${err}`);
    });
  }

  async isAlive() {
    return new Promise((resolve, reject) => {
      this.client.ping((err, reply) => {
        if (err) {
          reject(false);
        } else {
          resolve(true);
        }
      });
    });
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code defines the `RedisClient` class with the constructor, error handling, `isAlive`, `get`, `set`, and `del` functions as specified. Additionally, it creates an instance of the class named `redisClient` and exports it for use in other parts of your application.

