 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Create a slice of specific negative words.
2. Split the given sentence into words using Go's `strings.Fields` function.
3. Iterate through each word in the sliced sentence.
4. Check if the current word is in the slice of negative words or if the previous word is "not" and the current word is also a negative word.
5. If either condition is true, print a message indicating that the sentence contains a double negative.

Here's an example implementation:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "doesn't", "does not", "didn't", "don't", "haven't", "hadn't", "aren't", "aren't I", "aren't we", "aren't they", "wasn't", "was not", "weren't", "weren't we", "won't", "will not", "wouldn't", "would not"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Fields(sentence)
	lastNegative := false

	for i := 0; i < len(words); i++ {
		word := words[i]
		if contains(negativeWords, word) || lastNegative && contains(negativeWords, words[i]) {
			fmt.Println("Double Negative Detected!")
			return
		}
		lastNegative = false
	}

	fmt.Println("No Double Negative Found.")
}

func contains(slice []string, item string) bool {
	for _, a := range slice {
		if a == item {
			return true
		}
	}
	return false
}
```

